// Semua pengaturan dibaca dari environment variable (file .env), lihat README.
// Node ini juga memilih cerita berikutnya: dari antrian Google Sheets, dari webhook, atau kategori acak.

const env = (key, fallback = '') => {
  const v = $env[key];
  return v === undefined || v === null || String(v).trim() === '' ? fallback : String(v).trim();
};
const toInt = (v, fallback) => {
  const n = parseInt(v, 10);
  return Number.isFinite(n) ? n : fallback;
};
const toBool = (v) => /^(1|true|yes|ya|y|on)$/i.test(String(v ?? '').trim());
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const randInt = (lo, hi) => lo + Math.floor(Math.random() * (hi - lo + 1));

const fromWebhook = $('Webhook Manual').isExecuted;
const fromSchedule = $('Jadwal Posting').isExecuted;
const source = fromWebhook ? 'webhook' : fromSchedule ? 'jadwal' : 'manual';
const body = fromWebhook ? $('Validasi Webhook').first().json.body || {} : {};

const store = $getWorkflowStaticData('global');
const history = Array.isArray(store.history) ? store.history : [];

const dryRun = fromWebhook && body.dry_run !== undefined ? toBool(body.dry_run) : toBool(env('DRY_RUN', 'false'));

// --- Antrian Google Sheets (kalau GSHEET_URL diisi). Webhook yang menyebut kategori/ide tidak memakai antrian.
// ANTRIAN_MODE=urut      : baris diposting berurutan, satu per jadwal. tanggal/jam = paling cepat kapan boleh diposting.
// ANTRIAN_MODE=terjadwal : hanya baris yang punya tanggal/jam, diposting saat waktunya tiba.
let antrian = null;
const antrianPeringatan = [];
if ($('Ambil Antrian').isExecuted && !(body.kategori || body.ide)) {
  const res = $('Ambil Antrian').first().json;
  if (!res.ok) throw new Error('Antrian Google Sheets gagal dibaca: ' + (res.error || JSON.stringify(res).slice(0, 300)));
  const mode = env('ANTRIAN_MODE', 'urut').toLowerCase() === 'terjadwal' ? 'terjadwal' : 'urut';
  const zone = $now.zoneName;
  const parseFirst = (text, formats, opts) => {
    for (const f of formats) {
      const dt = DateTime.fromFormat(text, f, { zone, ...opts });
      if (dt.isValid) return dt;
    }
    return null;
  };
  // null = tanpa waktu, undefined = format tidak dikenali
  const parseWaktu = (tanggal, jam) => {
    tanggal = String(tanggal ?? '').trim();
    jam = String(jam ?? '').trim().toUpperCase();
    if (!tanggal && !jam) return null;
    let waktu = $now.startOf('day');
    if (tanggal) {
      waktu = parseFirst(tanggal, ['yyyy-MM-dd', 'd/M/yyyy', 'd-M-yyyy', 'd/M/yy', 'yyyy-MM-dd HH:mm']);
      if (!waktu) return undefined;
    }
    if (jam) {
      const t = parseFirst(jam, ['H:mm', 'H.mm', 'H:mm:ss', 'H.mm.ss', 'h:mm a', 'h:mm:ss a', 'h.mm a'], { locale: 'en' });
      if (!t) return undefined;
      waktu = waktu.set({ hour: t.hour, minute: t.minute, second: 0, millisecond: 0 });
    }
    return waktu;
  };

  const kandidat = [];
  for (const r of res.rows || []) {
    if (String(r.status ?? '').trim()) continue;
    if (!String(r.kategori ?? '').trim() && !String(r.ide ?? '').trim()) continue;
    const waktu = parseWaktu(r.tanggal, r.jam);
    if (waktu === undefined) {
      antrianPeringatan.push(`Baris ${r.row}: format tanggal/jam tidak dikenali ("${r.tanggal}" "${r.jam}")`);
      continue;
    }
    if (mode === 'terjadwal' && !waktu) continue;
    if (waktu && waktu > $now) continue;
    kandidat.push({ ...r, waktu });
  }
  if (mode === 'terjadwal') kandidat.sort((a, b) => a.waktu - b.waktu);

  const pick = kandidat[0];
  if (pick) {
    antrian = {
      row: pick.row,
      kategori: String(pick.kategori ?? '').trim(),
      ide: String(pick.ide ?? '').trim(),
      jumlah_bagian: toInt(pick.jumlah_bagian, 0),
      gambar: String(pick.gambar ?? '').trim(),
      waktu: pick.waktu ? pick.waktu.toFormat('yyyy-MM-dd HH:mm') : null,
    };
  } else if (fromSchedule && (mode === 'terjadwal' || env('ANTRIAN_KOSONG', 'acak').toLowerCase() === 'lewati')) {
    // Tidak ada baris yang waktunya tiba: jadwal kali ini dilewati
    return [];
  }
}
const pilihan = antrian || body;

// --- Kategori cerita: dari antrian/webhook, atau diacak dari STORY_NICHES (tidak sama dengan postingan terakhir)
const niches = env(
  'STORY_NICHES',
  'cerita horor kos-kosan|kisah lucu di kantor|kisah inspiratif perantau|cerita cinta masa SMA|kisah haru tentang orang tua'
)
  .split('|')
  .map((s) => s.trim())
  .filter(Boolean);
const ide = String(pilihan.ide || '').trim();
let kategori = String(pilihan.kategori || '').trim();
if (!kategori && ide) kategori = 'bebas, sesuaikan dengan ide cerita';
if (!kategori) {
  const last = history.length ? history[history.length - 1].kategori : null;
  const pool = niches.length > 1 ? niches.filter((n) => n !== last) : niches;
  kategori = pool[Math.floor(Math.random() * pool.length)];
}

// --- Jumlah bagian utas
const minParts = clamp(toInt(env('STORY_MIN_PARTS'), 3), 1, 10);
const maxParts = clamp(toInt(env('STORY_MAX_PARTS'), 6), minParts, 10);
const parts = clamp(toInt(pilihan.jumlah_bagian, 0) || randInt(minParts, maxParts), 1, 10);

// --- Token Threads: pakai token hasil refresh otomatis kalau ada, kalau tidak pakai dari .env
const envToken = env('THREADS_ACCESS_TOKEN');
const fingerprint = (t) => (t ? t.slice(-12) : '');
if (store.threadsToken && store.envTokenFingerprint !== fingerprint(envToken)) {
  // Token di .env sudah diganti manual, jadi token lama hasil refresh dibuang
  delete store.threadsToken;
  delete store.threadsTokenExpiresAt;
  delete store.envTokenFingerprint;
}
const threadsToken = store.threadsToken || envToken;
if (!dryRun && !threadsToken) throw new Error('THREADS_ACCESS_TOKEN belum diisi di file .env');
if (!env('ANTHROPIC_API_KEY')) throw new Error('ANTHROPIC_API_KEY belum diisi di file .env');

// --- Gambar di post pertama
// GAMBAR_SUMBER: off | pexels (foto stok sesuai cerita) | ai (ilustrasi AI) | url (acak dari GAMBAR_URLS)
// URL gambar dari kolom "gambar" di antrian atau field "gambar" di webhook selalu dipakai lebih dulu.
const gambarSumber = env('GAMBAR_SUMBER', 'off').toLowerCase();
if (!['off', 'pexels', 'ai', 'url'].includes(gambarSumber)) {
  throw new Error(`GAMBAR_SUMBER tidak dikenal: "${gambarSumber}". Pilihan: off, pexels, ai, url`);
}
if (gambarSumber === 'pexels' && !env('PEXELS_API_KEY')) throw new Error('GAMBAR_SUMBER=pexels butuh PEXELS_API_KEY di .env');
const gambar = {
  sumber: gambarSumber,
  manual: String(body.gambar || pilihan.gambar || '').trim(),
  kredit: toBool(env('GAMBAR_KREDIT', 'true')),
  gaya: env('GAMBAR_GAYA', 'cinematic digital illustration, moody lighting, rich colors'),
  aiUrl: env(
    'GAMBAR_AI_URL',
    'https://image.pollinations.ai/prompt/{prompt}?width=1080&height=1350&seed={seed}&nologo=true&model=flux'
  ),
  urls: env('GAMBAR_URLS')
    .split('|')
    .map((u) => u.trim())
    .filter(Boolean),
  jedaDetik: clamp(toInt(env('GAMBAR_JEDA_DETIK'), 30), 5, 120),
  terpakai: Array.isArray(store.gambarTerpakai) ? store.gambarTerpakai : [],
};
if (gambarSumber === 'url' && gambar.urls.length === 0) throw new Error('GAMBAR_SUMBER=url butuh daftar GAMBAR_URLS di .env');

const threadsHost = env('THREADS_API_HOST', 'https://graph.threads.net').replace(/\/+$/, '');
const jitterMinutes = clamp(toInt(env('POST_JITTER_MINUTES'), 0), 0, 55);

return [
  {
    json: {
      source,
      dryRun,
      kategori,
      ide,
      parts,
      antrian,
      antrianPeringatan,
      gambar,
      executionId: $execution.id,
      style: env(
        'STORY_STYLE',
        'Bahasa Indonesia santai sehari-hari pakai aku-kamu, seperti orang curhat di Threads. Kalimat pendek, jujur, dan relate.'
      ),
      persona: env('STORY_PERSONA'),
      extraInstructions: env('STORY_EXTRA_INSTRUCTIONS'),
      today: $now.setLocale('id').toFormat('cccc, d LLLL yyyy'),
      recentTitles: history.slice(-15).map((h) => `${h.judul} (${h.kategori})`),
      numbering: toBool(env('THREAD_NUMBERING', 'true')),
      topicTagMode: env('THREADS_TOPIC_TAG', 'auto'),
      claude: {
        model: env('AI_MODEL', 'claude-opus-5-5'),
        effort: env('AI_EFFORT', 'medium'),
        // "default" = kalau model menolak, API otomatis mencoba model cadangan. Isi "off" untuk mematikan.
        fallback: /^(off|false|no|0)$/i.test(env('AI_FALLBACK', 'default')) ? '' : 'default',
      },
      threadsApi: `${threadsHost}/v1.0`,
      threadsUserId: env('THREADS_USER_ID', 'me'),
      threadsToken,
      tokenSource: store.threadsToken ? 'refresh otomatis' : '.env',
      publishDelaySeconds: clamp(toInt(env('PUBLISH_DELAY_SECONDS'), 10), 1, 60),
      // Jeda acak hanya untuk posting terjadwal yang berjalan otomatis, supaya jam posting tidak terlalu kaku
      jitterSeconds: fromSchedule && $execution.mode === 'production' && jitterMinutes > 0 ? randInt(1, jitterMinutes * 60) : 1,
      historySize: clamp(toInt(env('HISTORY_SIZE'), 30), 1, 200),
    },
  },
];

// Prompt untuk Claude. Ubah aturan menulis di sini kalau pengaturan STORY_* di .env belum cukup.
const cfg = $('Siapkan Konfigurasi').first().json;

// Kalau post pertama diberi gambar, Claude juga diminta menuliskan kata kunci foto atau prompt ilustrasi
const butuhGambar = !cfg.gambar.manual && ['pexels', 'ai'].includes(cfg.gambar.sumber);

const system = [
  'Kamu penulis konten Threads berbahasa Indonesia yang ahli storytelling.',
  'Tugasmu menulis satu utas (thread) cerita yang membuat orang berhenti scroll dan membaca sampai habis.',
  '',
  'Aturan menulis:',
  '- Bagian pertama adalah hook: pembuka yang bikin penasaran tanpa membocorkan akhir cerita.',
  '- Setiap bagian maksimal 420 karakter, berisi satu momen, dan diakhiri dengan rasa penasaran supaya pembaca lanjut ke bagian berikutnya.',
  '- Bagian terakhir berisi penutup yang memuaskan (twist, pelajaran, atau punchline), lalu satu pertanyaan ringan ke pembaca untuk memancing balasan.',
  '- Kalimat pendek dan enak dibaca di HP. Boleh pakai baris baru di dalam satu bagian.',
  '- Tanpa hashtag, tanpa format markdown (tanda bintang, heading), dan tanpa penomoran bagian karena nomor ditambahkan otomatis.',
  '- Emoji secukupnya, paling banyak satu per bagian.',
  '- Cerita harus orisinal dan masuk akal. Jangan memakai nama asli tokoh publik atau merek, dan hindari SARA, konten dewasa, serta kekerasan eksplisit.',
  '',
  'Field "judul" berisi ringkasan ide cerita (maksimal 10 kata, tidak ikut diposting).',
  'Field "topic_tag" berisi satu topik Threads yang relevan (1-50 karakter, tanpa tanda #, titik, atau &), misalnya "Cerita Horor".',
  'Field "bagian" berisi teks setiap bagian utas secara berurutan.',
  butuhGambar && cfg.gambar.sumber === 'pexels'
    ? 'Field "gambar" berisi 2-4 kata kunci bahasa Inggris untuk mencari foto stok yang cocok dengan suasana pembuka cerita (bukan akhir/twist-nya), tanpa nama orang atau merek. Contoh: "old boarding house night".'
    : null,
  butuhGambar && cfg.gambar.sumber === 'ai'
    ? 'Field "gambar" berisi prompt bahasa Inggris (maksimal 40 kata) untuk ilustrasi yang menggambarkan suasana pembuka cerita (bukan akhir/twist-nya): tempat, objek, waktu, dan pencahayaan. Tanpa tulisan/teks di gambar, tanpa wajah orang sungguhan atau tokoh terkenal, aman untuk semua umur.'
    : null,
]
  .filter((line) => line !== null)
  .join('\n');

const user = [
  `Tulis satu utas cerita dengan tepat ${cfg.parts} bagian.`,
  '',
  `Kategori: ${cfg.kategori}`,
  cfg.ide ? `Ide cerita: ${cfg.ide}` : null,
  `Gaya bahasa: ${cfg.style}`,
  `Narator: ${cfg.persona || 'orang pertama ("aku") yang menceritakan pengalamannya sendiri'}`,
  cfg.extraInstructions ? `Instruksi tambahan: ${cfg.extraInstructions}` : null,
  `Hari ini: ${cfg.today}`,
  '',
  'Ide yang sudah pernah diposting (buat cerita yang berbeda dari daftar ini):',
  cfg.recentTitles.length ? cfg.recentTitles.map((t) => `- ${t}`).join('\n') : '(belum ada)',
]
  .filter((line) => line !== null)
  .join('\n');

const schema = {
  type: 'object',
  properties: {
    judul: { type: 'string', description: 'Ringkasan ide cerita, maksimal 10 kata' },
    topic_tag: { type: 'string', description: 'Satu topik Threads, 1-50 karakter, tanpa #, titik, atau &' },
    bagian: { type: 'array', items: { type: 'string' }, description: 'Teks setiap bagian utas secara berurutan' },
  },
  required: ['judul', 'topic_tag', 'bagian'],
  additionalProperties: false,
};
if (butuhGambar) {
  schema.properties.gambar = {
    type: 'string',
    description: cfg.gambar.sumber === 'pexels' ? 'Kata kunci foto stok (bahasa Inggris)' : 'Prompt ilustrasi (bahasa Inggris)',
  };
  schema.required.push('gambar');
}

const body = {
  model: cfg.claude.model,
  max_tokens: 16000,
  system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
};
if (cfg.claude.effort) body.output_config.effort = cfg.claude.effort;
if (cfg.claude.fallback) body.fallbacks = cfg.claude.fallback;

const headers = { 'anthropic-version': '2023-06-01', 'content-type': 'application/json' };
if (body.fallbacks) headers['anthropic-beta'] = 'server-side-fallback-2026-07-01';

return [{ json: { claudeBody: body, claudeHeaders: headers } }];

// Ubah jawaban Claude jadi daftar postingan siap kirim (batas Threads: 500 karakter per post).
const cfg = $('Siapkan Konfigurasi').first().json;
const res = $input.first().json;

if (res.stop_reason === 'refusal') {
  throw new Error('Claude menolak membuat cerita ini (stop_reason: refusal). Coba ganti kategori atau instruksi.');
}
if (res.stop_reason === 'max_tokens') {
  throw new Error('Jawaban Claude terpotong (stop_reason: max_tokens). Kurangi jumlah bagian.');
}
const raw = (res.content || [])
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('');
let story;
try {
  story = JSON.parse(raw);
} catch (e) {
  throw new Error('Jawaban Claude bukan JSON yang valid: ' + raw.slice(0, 300));
}
if (!Array.isArray(story.bagian) || story.bagian.length === 0) {
  throw new Error('Claude tidak mengembalikan bagian cerita.');
}

// Threads menghitung karakter non-ASCII (misalnya emoji) per byte UTF-8, jadi dihitung dengan cara yang sama.
const weight = (s) => {
  let n = 0;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    n += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
  }
  return n;
};

const clean = (s) =>
  String(s)
    .replace(/\r\n/g, '\n')
    .replace(/\*\*|__/g, '')
    .replace(/^\s*(?:\(?\d{1,2}\s*\/\s*\d{0,2}\)?|\d{1,2}[.)])\s+/, '') // nomor bagian buatan model
    .replace(/(^|\s)#[\p{L}\p{N}_]+/gu, '$1') // hashtag
    .replace(/[ \t]+\n/g, '\n')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

// Pecah teks yang kepanjangan per kalimat jadi beberapa post yang panjangnya kira-kira sama
// (per kata kalau satu kalimat pun masih kepanjangan)
const chunk = (text, max) => {
  if (weight(text) <= max) return [text];
  const target = Math.ceil(weight(text) / Math.ceil(weight(text) / max));
  const sentences = text.match(/[^.!?…\n]*[.!?…]+["”’')]*\s*|[^.!?…\n]+\s*|\n+/g) || [text];
  const out = [];
  let cur = '';
  const flush = () => {
    if (cur.trim()) out.push(cur.trim());
    cur = '';
  };
  for (const s of sentences) {
    if (weight(s) > max) {
      flush();
      for (const w of s.split(/\s+/).filter(Boolean)) {
        const next = cur ? `${cur} ${w}` : w;
        if (weight(next) <= max) {
          cur = next;
          continue;
        }
        flush();
        for (const ch of w) {
          if (weight(cur + ch) > max) flush();
          cur += ch;
        }
      }
      continue;
    }
    if (weight(cur + s) > max || weight(cur) >= target) flush();
    cur += s;
  }
  flush();
  return out;
};

const LIMIT = 500;
const reserve = cfg.numbering ? 10 : 0; // ruang untuk "\n\n(10/10)"
const posts = story.bagian
  .map(clean)
  .filter(Boolean)
  .flatMap((t) => chunk(t, LIMIT - reserve));
if (posts.length === 0) throw new Error('Semua bagian cerita kosong setelah dibersihkan.');

const sanitizeTag = (t) =>
  [...String(t || '').replace(/[#.&]/g, '').replace(/\s+/g, ' ').trim()].slice(0, 50).join('').trim();
const tagMode = cfg.topicTagMode.toLowerCase();
const topicTag =
  tagMode === 'auto' ? sanitizeTag(story.topic_tag) : /^(off|none|false|0)$/.test(tagMode) ? '' : sanitizeTag(cfg.topicTagMode);

return posts.map((text, i) => {
  const finalText = cfg.numbering && posts.length > 1 ? `${text}\n\n(${i + 1}/${posts.length})` : text;
  return {
    json: {
      index: i,
      total: posts.length,
      text: finalText,
      panjang: weight(finalText),
      topic_tag: i === 0 ? topicTag : '',
      judul: String(story.judul || '').trim(),
      // Kata kunci foto / prompt ilustrasi dari Claude (hanya ada kalau GAMBAR_SUMBER=pexels/ai)
      gambar_ide: i === 0 ? String(story.gambar || '').trim() : '',
      kategori: cfg.kategori,
      dryRun: cfg.dryRun,
    },
  };
});

// Tentukan gambar untuk post pertama. Gambarnya diunduh dulu untuk dicek sebelum dikirim ke Threads.
const cfg = $('Siapkan Konfigurasi').first().json;
const g = cfg.gambar;
const ide = $input.first().json.gambar_ide || '';

let plan = { sumber: 'off' };
if (g.manual) {
  plan = /^https?:\/\//i.test(g.manual)
    ? { sumber: 'manual', url: g.manual }
    : { sumber: 'manual', url: '', peringatan: `Isi kolom gambar bukan URL: "${g.manual.slice(0, 80)}"` };
} else if (g.sumber === 'pexels') {
  plan = { sumber: 'pexels', query: ide || cfg.kategori };
} else if (g.sumber === 'ai') {
  const prompt = [ide || `a scene from a story about ${cfg.kategori}`, g.gaya, 'no text, no watermark'].join(', ');
  const seed = String(Math.floor(Math.random() * 1e9));
  const url = g.aiUrl.split('{prompt}').join(encodeURIComponent(prompt)).split('{seed}').join(seed);
  plan = { sumber: 'ai', url, prompt };
} else if (g.sumber === 'url') {
  // Utamakan gambar yang belum pernah dipakai
  const belum = g.urls.filter((u) => !g.terpakai.includes(u));
  const pool = belum.length ? belum : g.urls;
  const url = pool[Math.floor(Math.random() * pool.length)];
  plan = { sumber: 'url', url, id: url };
}

return [{ json: { plan } }];

// Pilih satu foto dari hasil pencarian Pexels (utamakan yang belum pernah dipakai), dipotong portrait 1080x1350.
const cfg = $('Siapkan Konfigurasi').first().json;
const plan = $('Rencana Gambar').first().json.plan;
const res = $input.first().json;

if (!Array.isArray(res.photos)) {
  const alasan = res.error?.message || res.error || JSON.stringify(res).slice(0, 200);
  return [{ json: { plan: { ...plan, url: '', peringatan: `Pencarian Pexels gagal: ${alasan}` } } }];
}
const terpakai = new Set(cfg.gambar.terpakai.map(String));
const baru = res.photos.filter((p) => !terpakai.has(`pexels:${p.id}`));
const pool = (baru.length ? baru : res.photos).slice(0, 5);
if (pool.length === 0) {
  return [{ json: { plan: { ...plan, url: '', peringatan: `Tidak ada foto Pexels untuk "${plan.query}"` } } }];
}

const foto = pool[Math.floor(Math.random() * pool.length)];
const asli = String(foto.src?.original || '').split('?')[0];
return [
  {
    json: {
      plan: {
        ...plan,
        url: `${asli}?auto=compress&cs=tinysrgb&fit=crop&w=1080&h=1350`,
        id: `pexels:${foto.id}`,
        fotografer: foto.photographer || '',
        halaman: foto.url || '',
      },
    },
  },
];

// Pasang gambar ke post pertama kalau gambarnya valid (JPEG/PNG, maksimal 8 MB).
// Kalau gambar gagal didapat, utas tetap diposting tanpa gambar dan alasannya dicatat.
const cfg = $('Siapkan Konfigurasi').first().json;
const posts = $('Olah Cerita').all().map((i) => ({ ...i.json }));
const plan = $('Pilih Foto').isExecuted ? $('Pilih Foto').first().json.plan : $('Rencana Gambar').first().json.plan;

const weight = (s) => {
  let n = 0;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    n += cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
  }
  return n;
};
const toBytes = (b) => {
  if (Number(b.bytes) > 0) return Number(b.bytes);
  const m = String(b.fileSize || '').match(/([\d.]+)\s*(B|kB|KB|MB|GB)/);
  const unit = { B: 1, kB: 1e3, KB: 1e3, MB: 1e6, GB: 1e9 };
  return m ? Number(m[1]) * unit[m[2]] : 0;
};

let url = '';
let peringatan = plan.peringatan || '';
if (plan.url) {
  const unduhan = $('Unduh Gambar').isExecuted ? $input.first() : null;
  const bin = unduhan?.binary?.data;
  const asal = plan.sumber === 'ai' ? 'Gambar AI' : 'Gambar';
  if (!bin) {
    peringatan = `${asal} tidak bisa diunduh: ${String(unduhan?.json?.error?.message || 'tidak ada data').slice(0, 150)}`;
  } else if (!/^image\/(jpeg|jpg|png)$/i.test(bin.mimeType || '')) {
    peringatan = `${asal} berformat ${bin.mimeType || 'tidak dikenal'}, padahal Threads hanya menerima JPEG/PNG`;
  } else if (toBytes(bin) > 8 * 1024 * 1024) {
    peringatan = `${asal} lebih dari 8 MB (${bin.fileSize})`;
  } else {
    url = plan.url;
  }
}

if (url) {
  posts[0].image_url = url;
  // Kredit fotografer Pexels, hanya kalau masih muat di batas 500 karakter
  if (plan.sumber === 'pexels' && cfg.gambar.kredit && plan.fotografer) {
    const dengan = `${posts[0].text}\n📷 ${plan.fotografer} / Pexels`;
    if (weight(dengan) <= 500) {
      posts[0].text = dengan;
      posts[0].panjang = weight(dengan);
    }
  }
}
posts[0].gambar = {
  sumber: url ? plan.sumber : 'tanpa gambar',
  url,
  id: url ? plan.id || '' : '',
  fotografer: url ? plan.fotografer || '' : '',
  peringatan,
};

return posts.map((json) => ({ json }));

// Mode uji (DRY_RUN): cerita hanya ditampilkan di sini, tidak diposting ke Threads.
// Kalau cerita diambil dari antrian Google Sheets, status barisnya tidak diubah.
const cfg = $('Siapkan Konfigurasi').first().json;
const posts = $input.all().map((i) => i.json);

return [
  {
    json: {
      ok: true,
      dry_run: true,
      pesan: 'Mode uji: cerita TIDAK diposting ke Threads.',
      judul: posts[0].judul,
      kategori: posts[0].kategori,
      antrian_baris: cfg.antrian ? cfg.antrian.row : null,
      antrian_peringatan: cfg.antrianPeringatan,
      topic_tag: posts[0].topic_tag,
      gambar: posts[0].gambar,
      jumlah_bagian: posts.length,
      bagian: posts.map((p) => p.text),
      panjang_karakter: posts.map((p) => p.panjang),
    },
  },
];

// Cek status container sebelum dipublikasikan. Kalau Threads gagal memproses media, berhenti dengan pesan jelas.
// Status IN_PROGRESS (gambar masih diproses) ditangani oleh percobaan ulang di node Publish Bagian.
const res = $input.first().json;
const status = String(res.status || '').toUpperCase();
if (status === 'ERROR' || status === 'EXPIRED') {
  throw new Error(
    `Threads gagal memproses post (status ${status}${res.error_message ? `, ${res.error_message}` : ''}). ` +
      'Kalau ini post bergambar, pastikan URL gambarnya publik dan berformat JPEG/PNG.'
  );
}
return [{ json: { id: res.id, status } }];

// Simpan riwayat cerita (supaya ide tidak berulang) dan tampilkan ringkasan hasil posting.
const cfg = $('Siapkan Konfigurasi').first().json;
const posts = $('Hasil Gambar').all().map((i) => i.json);
const gambar = posts[0].gambar;
const postIds = posts.map((_, run) => $('Publish Bagian').first(0, run)?.json?.id).filter(Boolean);
const permalink = $input.first().json.permalink || null;

const store = $getWorkflowStaticData('global');
const history = Array.isArray(store.history) ? store.history : [];
history.push({
  judul: posts[0].judul,
  kategori: posts[0].kategori,
  waktu: $now.toISO(),
  post_id: postIds[0] || null,
  permalink,
});
store.history = history.slice(-cfg.historySize);
if (gambar.id) {
  // Ingat gambar yang sudah dipakai supaya tidak berulang
  const terpakai = Array.isArray(store.gambarTerpakai) ? store.gambarTerpakai : [];
  store.gambarTerpakai = [...terpakai.filter((x) => x !== gambar.id), gambar.id].slice(-100);
}

return [
  {
    json: {
      ok: true,
      pesan: `Utas ${postIds.length} bagian berhasil diposting.`,
      sumber: cfg.source,
      antrian_baris: cfg.antrian ? cfg.antrian.row : null,
      judul: posts[0].judul,
      kategori: posts[0].kategori,
      topic_tag: posts[0].topic_tag,
      gambar,
      permalink,
      post_ids: postIds,
      token_dari: cfg.tokenSource,
      token_kedaluwarsa: store.threadsTokenExpiresAt || 'tidak diketahui (token dari .env)',
    },
  },
];

// Ambil token Threads yang sedang dipakai (hasil refresh terakhir, atau dari .env).
const envToken = String($env.THREADS_ACCESS_TOKEN || '').trim();
const fingerprint = (t) => (t ? t.slice(-12) : '');
const store = $getWorkflowStaticData('global');

const useStored = store.threadsToken && store.envTokenFingerprint === fingerprint(envToken);
const token = useStored ? store.threadsToken : envToken;
if (!token) throw new Error('THREADS_ACCESS_TOKEN belum diisi di file .env');

const host = String($env.THREADS_API_HOST || 'https://graph.threads.net').trim().replace(/\/+$/, '');

return [{ json: { token, host } }];

// Simpan token baru. Token long-lived Threads berlaku 60 hari dan diperpanjang setiap kali di-refresh.
const res = $input.first().json;
if (!res.access_token) throw new Error('Refresh token gagal: ' + JSON.stringify(res).slice(0, 300));

const envToken = String($env.THREADS_ACCESS_TOKEN || '').trim();
const store = $getWorkflowStaticData('global');
const expiresAt = $now.plus({ seconds: Number(res.expires_in) || 0 }).toISO();

store.threadsToken = res.access_token;
store.threadsTokenExpiresAt = expiresAt;
store.envTokenFingerprint = envToken ? envToken.slice(-12) : '';

return [{ json: { ok: true, pesan: 'Token Threads berhasil diperpanjang.', berlaku_sampai: expiresAt } }];

// Susun pesan notifikasi Telegram. Kalau Telegram belum diatur di .env, node ini tidak mengeluarkan apa-apa
// sehingga node "Kirim Telegram" tidak dijalankan.
// TELEGRAM_NOTIFY: "semua" (default) = posting, mode uji, perpanjang token, dan error; "error" = error saja; "off" = mati.
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chatId = String($env.TELEGRAM_CHAT_ID || '').trim();
const mode = String($env.TELEGRAM_NOTIFY || 'semua').trim().toLowerCase();
if (!token || !chatId || /^(off|false|no|0)$/.test(mode)) return [];

const d = $input.first().json;
const MAX = 3900; // batas Telegram 4096 karakter per pesan
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const tanggal = (iso) => (iso ? DateTime.fromISO(iso, { setZone: true }).setLocale('id').toFormat('d LLLL yyyy, HH:mm') : '-');

// Info gambar post pertama. Di pesan mode uji, link gambar disertakan supaya Telegram menampilkan pratinjaunya.
const gambarInfo = (g, denganLink) => {
  if (!g) return null;
  if (g.url) {
    const asal = g.sumber === 'pexels' && g.fotografer ? `Pexels, ${g.fotografer}` : g.sumber;
    return denganLink ? `🖼️ Gambar (${asal}): ${g.url}` : `🖼️ Dengan gambar (${asal})`;
  }
  return g.peringatan ? `⚠️ Tanpa gambar: ${g.peringatan}` : null;
};

let messages = [];

if ($('Kalau Error').isExecuted) {
  const err = d.execution?.error || d.trigger?.error || {};
  messages.push(
    [
      '❌ Threads AutoPost gagal',
      '',
      `Node: ${d.execution?.lastNodeExecuted || err.node?.name || '-'}`,
      `Error: ${cut(String(err.message || 'tidak diketahui').replace(/\s*\[line \d+\]$/, ''), 500)}`,
      err.description ? `Detail: ${cut(String(err.description), 800)}` : null,
      d.execution?.url ? `\nLihat di n8n: ${d.execution.url}` : null,
    ]
      .filter((l) => l !== null)
      .join('\n')
  );
} else if (mode === 'error') {
  return [];
} else if ($('Ringkasan & Riwayat').isExecuted) {
  messages.push(
    [
      '✅ Utas baru terposting',
      '',
      `Judul: ${d.judul}`,
      `Kategori: ${d.kategori}`,
      `Bagian: ${d.post_ids.length}${d.topic_tag ? ` · Topik: ${d.topic_tag}` : ''}`,
      d.antrian_baris ? `Dari antrian Google Sheets baris ${d.antrian_baris}` : null,
      gambarInfo(d.gambar, false),
      '',
      d.permalink || 'Link belum tersedia, cek langsung di Threads.',
    ]
      .filter((l) => l !== null)
      .join('\n')
  );
} else if ($('Pratinjau (Dry Run)').isExecuted) {
  // Kirim cerita lengkap supaya bisa dibaca dari HP. Kalau kepanjangan, dipecah jadi beberapa pesan.
  const header = [
    '🧪 Mode uji — cerita TIDAK diposting',
    `Judul: ${d.judul}`,
    `Kategori: ${d.kategori}${d.topic_tag ? ` · Topik: ${d.topic_tag}` : ''}`,
    d.antrian_baris ? `Dari antrian baris ${d.antrian_baris} (status baris tidak diubah)` : null,
    ...(d.antrian_peringatan || []).map((w) => `⚠️ ${w}`),
    gambarInfo(d.gambar, true),
  ]
    .filter((l) => l !== null)
    .join('\n');
  let cur = header;
  for (const part of d.bagian) {
    const block = `\n\n———\n\n${part}`;
    if (cur.length + block.length > MAX) {
      messages.push(cur);
      cur = part;
    } else {
      cur += block;
    }
  }
  messages.push(cur);
} else if ($('Simpan Token Baru').isExecuted) {
  messages.push(`🔑 Token Threads berhasil diperpanjang.\nBerlaku sampai: ${tanggal(d.berlaku_sampai)}`);
}

return messages.map((text) => ({ json: { text } }));

// Tulis hasil ke baris antrian Google Sheets: "terposting" (dengan judul & link) atau "gagal" (dengan pesan error).
// Kalau GSHEET_URL kosong, atau cerita ini tidak berasal dari antrian, node ini tidak mengeluarkan apa-apa.
if (!String($env.GSHEET_URL || '').trim()) return [];
const waktu = $now.toFormat('yyyy-MM-dd HH:mm');
const d = $input.first().json;

if ($('Kalau Error').isExecuted) {
  // Baris yang sedang "diproses" oleh eksekusi yang gagal dicari lewat nomor eksekusinya
  if (!d.execution?.id) return [];
  const err = d.execution.error || {};
  const pesan = [d.execution.lastNodeExecuted, err.description || err.message].filter(Boolean).join(': ');
  return [{ json: { query: { action: 'update', exec: String(d.execution.id), status: 'gagal', catatan: `gagal ${waktu} — ${pesan}`.slice(0, 500) } } }];
}

const cfg = $('Siapkan Konfigurasi').first().json;
if (!cfg.antrian) return [];
return [
  {
    json: {
      query: {
        action: 'update',
        row: String(cfg.antrian.row),
        status: 'terposting',
        judul: d.judul,
        link: d.permalink || '',
        catatan: `diposting ${waktu}${d.gambar?.peringatan ? ` — tanpa gambar: ${d.gambar.peringatan}` : ''}`.slice(0, 500),
      },
    },
  },
];
